#define GL_SILENCE_DEPRECATION
#include <OpenGL/OpenGL.h>
#include <OpenGL/gl3.h>
#include "../host/file_assets.hpp"
#include "../app/color_grading_renderer.hpp"
#include <algorithm>
#include <array>
#include <cmath>
#include <iostream>
#include <stdexcept>
using Pixel=std::array<uint8_t,4>;
std::array<float,4> sample(const hades::ColorVolume*v,Pixel p){std::array<float,4>out{};if(!v){for(int i=0;i<4;++i)out[i]=p[i]/255.f;return out;}std::array<int,3>a{},b{};std::array<float,3>f{};for(int i=0;i<3;++i){float t=(p[i]/255.f)*(v->size-1);a[i]=int(t);b[i]=std::min(a[i]+1,int(v->size)-1);f[i]=t-a[i];}for(int z=0;z<2;++z)for(int y=0;y<2;++y)for(int x=0;x<2;++x){float w=(x?f[0]:1-f[0])*(y?f[1]:1-f[1])*(z?f[2]:1-f[2]);const size_t at=((size_t(z?b[2]:a[2])*v->size+(y?b[1]:a[1]))*v->size+(x?b[0]:a[0]))*4;for(int c=0;c<4;++c)out[c]+=w*v->rgba[at+c]/255.f;}return out;}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("color-grading-gpu ORIGINAL_COLOR_BANK_ROOT");hades::FileAssets assets(argv[1]);hades::ColorGrading grading;grading.load(assets);std::string error;
 const CGLPixelFormatAttribute at[]{kCGLPFAOpenGLProfile,static_cast<CGLPixelFormatAttribute>(kCGLOGLPVersion_3_2_Core),kCGLPFAColorSize,static_cast<CGLPixelFormatAttribute>(24),kCGLPFAAlphaSize,static_cast<CGLPixelFormatAttribute>(8),static_cast<CGLPixelFormatAttribute>(0)};CGLPixelFormatObj pf=nullptr;CGLContextObj context=nullptr;GLint count=0;if(CGLChoosePixelFormat(at,&pf,&count)||!pf||CGLCreateContext(pf,nullptr,&context))throw std::runtime_error("GPU context failed");CGLDestroyPixelFormat(pf);CGLSetCurrentContext(context);
 std::array<Pixel,8> pixels{{{0,0,0,255},{255,255,255,255},{255,0,0,255},{0,255,0,255},{0,0,255,255},{61,120,20,225},{137,45,207,180},{83,211,93,255}}};GLuint texture=0,fbo=0;glGenTextures(1,&texture);glBindTexture(GL_TEXTURE_2D,texture);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,8,1,0,GL_RGBA,GL_UNSIGNED_BYTE,pixels.data());glGenFramebuffers(1,&fbo);glBindFramebuffer(GL_FRAMEBUFFER,fbo);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,texture,0);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)throw std::runtime_error("GPU target incomplete");glViewport(0,0,8,1);hades::ColorGradingRenderer renderer;unsigned checked=0;int maxError=0;
 const auto check=[&]{glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,texture);glTexSubImage2D(GL_TEXTURE_2D,0,0,0,8,1,GL_RGBA,GL_UNSIGNED_BYTE,pixels.data());renderer.render(grading,8,1);std::array<Pixel,8>actual{};glReadPixels(0,0,8,1,GL_RGBA,GL_UNSIGNED_BYTE,actual.data());for(size_t i=0;i<pixels.size();++i){const auto a=sample(grading.previous(),pixels[i]),b=sample(grading.current(),pixels[i]);for(size_t c=0;c<4;++c){int expected=int(std::lround((a[c]+(b[c]-a[c])*grading.fraction())*255));int diff=std::abs(int(actual[i][c])-expected);maxError=std::max(maxError,diff);if(diff>1)throw std::runtime_error("Original LUT GPU/independent CPU mismatch");}++checked;}};
 const auto set=[&](const char*n,float duration,bool world,float wt,float st){if(!grading.set(n,duration,world,wt,st,error))throw std::runtime_error(error);};const auto advance=[&](float w,float s){if(!grading.advance(w,s,error))throw std::runtime_error(error);};
 check();set("Dusk",0,true,0,0);check();set("Off",1,true,3,10);advance(3.5,90);if(grading.fraction()!=.5f)throw std::runtime_error("World clock selection wrong");check();advance(4,90);if(grading.active())throw std::runtime_error("Completed Off should skip GPU");check();set("Dusk",0,true,4,90);set("WeatherSnowCinders",2,false,4,90);advance(8,90.5);if(grading.fraction()!=.25f||grading.current()->size!=16||grading.previous()->size!=32)throw std::runtime_error("Actual16/32 volume/clock transition wrong");check();set("NightBlue",2,true,8,90.5);if(grading.previousName()!="WeatherSnowCinders")throw std::runtime_error("Interrupted native transition must retain old target");advance(9,90.5);check();renderer.shutdown();renderer.render(grading,8,1);check();renderer.shutdown();glDeleteFramebuffers(1,&fbo);glDeleteTextures(1,&texture);CGLSetCurrentContext(nullptr);CGLDestroyContext(context);
 std::cout<<"{\"result\":\"passed\",\"real_source_volume_pixel_checks\":"<<checked<<",\"maximum_rgba_byte_error\":"<<maxError<<",\"source_16_to_32_cube_transition\":true,\"world_and_screen_clocks\":true,\"interrupted_target_semantics\":true,\"GL_resource_recreation\":true,\"android_observed\":false}\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
